      <div className="flex justify-between items-end px-3 pt-1 pb-0.5 shrink-0 h-[8mm]">
        <div className="flex flex-col justify-center">
           <span className="text-[9px] uppercase text-gray-600 font-bold leading-none mb-0.5">Rok instalacji</span>
