        </div>
        <div className="text-right flex flex-col items-end justify-center">
           <div className="flex items-baseline gap-4">
              {data.rackNumber && (
                <span className="text-lg font-bold">NR: {data.rackNumber}</span>
              )}
              <span className="text-base font-bold uppercase">{data.customerName}</span>
           </div>
           <div className="text-[9px] leading-tight mt-0.5 text-gray-600">
             PROJEKT: <b className="text-xs text-black">{data.projectNumber}</b> <span className="ml-2">SAP: <b className="text-xs text-black">46120{data.sapNumberSuffix}</b></span>
           </div>
        </div>
      </div>

      {/* Main Table Content - Dynamic Height */}
      <div className={`w-full ${borderOuter} flex flex-col text-sm mx-0.5 mb-0.5 self-center max-w-[99.5%] bg-white`}>
        {/* Row 1: Max height of 1st level */}
        <div className={`flex ${borderInner} shrink-0 bg-white`}>
          <div className={`w-[70%] px-3 py-[1px] flex items-center ${borderRight}`}>
            <span className={`text-[10px] ${labelClass}`}>Max. wysokość 1. poziomu</span>
          </div>
          {!hasSecondConfig ? (
            <div className={`w-[30%] px-2 py-[1px] text-center flex items-baseline justify-center bg-white`}>
              <span className={levelLabelClass}>A =</span>
              <span className="text-base font-bold leading-none">{data.firstLevelHeight}<span className={unitClass}>mm</span></span>
            </div>
          ) : (
            <>
              <div className={`w-[15%] px-1 py-[1px] text-center flex items-baseline justify-center bg-white border-r border-black`}>
                <span className="text-[11px] font-bold text-gray-700 mr-1">A=</span>
                <span className="text-sm font-bold leading-none whitespace-nowrap">{data.firstLevelHeight}<span className={unitClass}>mm</span></span>
              </div>
              <div className={`w-[15%] px-1 py-[1px] text-center flex items-baseline justify-center bg-white`}>
                 {data.firstLevelHeight2 && (
                    <>
                      <span className="text-[11px] font-bold text-gray-700 mr-1">A=</span>
                      <span className="text-sm font-bold leading-none whitespace-nowrap">{data.firstLevelHeight2}<span className={unitClass}>mm</span></span>
                    </>
                 )}
              </div>
            </>
          )}
        </div>

        {/* Dynamic Rows: Subsequent Levels */}
        <div className="flex flex-col shrink-0">
          {!hasSecondConfig ? (
            data.subsequentLevels.map((level, idx) => ( 
              <div key={level.id} className={`flex border-b border-black last:border-b-0`}>
                <div className={`w-[70%] px-3 py-[1px] flex items-center ${borderRight}`}>
                  <span className={`text-[10px] ${labelClass}`}>{idx === 0 ? "Kolejne poziomy" : "\u00A0"}</span>
                </div>
                <div className={`w-[30%] px-2 py-[1px] text-center flex items-baseline justify-center`}>
                  <span className={levelLabelClass}>{`${getLevelLabel(level, 'A')} =`}</span>
                  <span className="text-base font-bold leading-none">{level.height}<span className={unitClass}>mm</span></span>
                </div>
              </div>
            ))
          ) : (
             rows.map((idx) => { 
               const l1 = data.subsequentLevels[idx];
               const l2 = data.subsequentLevels2 ? data.subsequentLevels2[idx] : undefined;
               return (
                <div key={idx} className={`flex border-b border-black last:border-b-0`}>
                  <div className={`w-[70%] px-3 py-[1px] flex items-center ${borderRight}`}>
                    <span className={`text-[10px] ${labelClass}`}>{idx === 0 ? "Kolejne poziomy" : "\u00A0"}</span>
                  </div>
                  <div className={`w-[15%] px-1 py-[1px] text-center flex items-baseline justify-center border-r border-black`}>
                    {l1 && (
                      <div className="flex items-baseline justify-center whitespace-nowrap">
                         <span className="text-[11px] font-bold mr-1 text-gray-700">{`${getLevelLabel(l1, 'A')} =`}</span>
                         <span className="text-sm font-bold leading-none">{l1.height}<span className={unitClass}>mm</span></span>
                      </div>
                    )}
                  </div>
                  <div className={`w-[15%] px-1 py-[1px] text-center flex items-baseline justify-center`}>
                     {l2 && (
                      <div className="flex items-baseline justify-center whitespace-nowrap">
                         <span className="text-[11px] font-bold mr-1 text-gray-700">{`${getLevelLabel(l2, 'B')} =`}</span>
                         <span className="text-sm font-bold leading-none">{l2.height}<span className={unitClass}>mm</span></span>
                      </div>
                    )}
                  </div>
                </div>
               );
             })
          )}
        </div>

        <div className={`bg-white text-black text-center py-0.5 text-[9px] uppercase tracking-tighter shrink-0 font-extrabold border-t-2 border-b-2 border-black leading-none`}>
          Maksymalne obciążenie pary trawersów
        </div>

        {/* Table Header for Beams */}
        <div className={`flex border-b border-black shrink-0 bg-white text-[9px] uppercase font-bold text-gray-600`}>
          <div className={`w-[15%] text-center py-0.5 ${borderRight}`}>Poziom</div>
          <div className={`w-[15%] text-center py-0.5 ${borderRight}`}>Dł. (L)</div>
          <div className={`w-[35%] text-center py-0.5 ${borderRight}`}>Profil</div>
          <div className={`w-[35%] text-center py-0.5`}>Max. Obciążenie</div>
        </div>

        {/* Dynamic Rows: Beams */}
        <div className="flex flex-col shrink-0">
          {data.beams.map((beam) => { 
            const qMax = calculateQmax(beam.loadCount, beam.loadWeight);
            return (
              <div key={beam.id} className={`flex border-b border-black last:border-b-0`}>
                <div className={`w-[15%] flex justify-center items-center px-1 text-sm font-bold ${borderRight} leading-none`}>
                   {beam.levelLabel}
                </div>
                <div className={`w-[15%] flex justify-center items-baseline px-1 text-lg font-bold ${borderRight} leading-none`}>
                  {beam.length}<span className={unitClass}>mm</span>
                </div>
                <div className={`w-[35%] text-center font-bold flex flex-row justify-center items-center gap-1 ${borderRight} leading-none py-0.5`}>
                  <span className="text-base whitespace-nowrap leading-none">{`AUF'B'${beam.profileType}`}</span>
                  <span className="text-[11px] text-gray-400 whitespace-nowrap leading-none">{`(${beam.profileWidth}x50)`}</span>
                </div>
                <div className={`w-[35%] flex flex-col justify-center items-center px-1 py-0.5`}>
                  <div className="flex flex-row items-baseline gap-3 leading-none">
                    <div className="flex items-baseline text-base font-bold leading-none">
                      <span className="text-[9px] mr-1 text-gray-400">Qmax=</span>
                      {qMax}<span className={unitClass}>kg</span>
                    </div>
                    <div className="text-[9px] text-gray-400 leading-none font-semibold">
                      {`${beam.loadCount}x${beam.loadWeight}`}<span className={unitClass}>kg</span>
                    </div>
                  </div>
                </div>
              </div>
            );
          })}
        </div>

        {/* Frame Info */}
        <div className={`flex border-t-2 border-b border-black shrink-0 bg-white`}>
           <div className={`w-[30%] text-center text-[10px] font-bold uppercase py-0.5 ${borderRight} flex items-center justify-center`}>
             <span className={labelClass}>Rama</span>
           </div>
           <div className={`w-[70%] text-center text-base font-bold py-0.5 flex flex-wrap items-center justify-center tracking-tight leading-tight px-1`}>
             {`STD'B'${data.frameType}'${data.frameDepth}'${data.frameHeight}`}
             {data.frameType2 && (
               <span className="text-[10px] mx-1 font-normal text-gray-500 lowercase">oraz</span>
             )}
             {data.frameType2 && (
               <span>{`STD'B'${data.frameType2}'${data.frameDepth2}'${data.frameHeight2}`}</span>
             )}
           </div>
        </div>

        {/* Max Bay Load */}
        <div className={`flex border-b border-black shrink-0 bg-white`}>
           <div className={`w-[60%] px-3 text-[10px] font-bold uppercase py-0.5 ${borderRight} flex items-center leading-none`}>
             <span className={labelClass}>max. obciążenie pola</span>
           </div>
           <div className={`w-[10%] text-center text-xs font-bold py-0.5 ${borderRight} flex items-center justify-center text-gray-600 leading-none`}>
             Qp=
           </div>
           <div className={`w-[30%] text-center text-lg font-bold py-0.5 flex items-baseline justify-center leading-none`}>
             {totalBayLoad}<span className={unitClass}>kg</span>
           </div>
        </div>

        {/* Rack Height */}
        <div className={`flex shrink-0 bg-white`}>
           <div className={`w-[60%] px-3 text-[10px] font-bold uppercase py-0.5 ${borderRight} flex items-center leading-none`}>
             <span className={labelClass}>Wysokość regału</span>
           </div>
           <div className={`w-[10%] text-center text-xs font-bold py-0.5 ${borderRight} flex items-center justify-center text-gray-600 leading-none`}>
             H=
           </div>
           <div className={`w-[30%] text-center text-lg font-bold py-0.5 flex items-baseline justify-center leading-none`}>
             {`${rackHeight}`}<span className={unitClass}>mm</span>
           </div>
        </div>
      </div>

      {/* Footer Address and Inspection - Reduced height from 12mm to 10mm */}
      <div className={`w-[99%] mx-auto flex border-t-2 border-black h-[10mm] shrink-0 mb-1 bg-white relative z-10 mt-auto`}>
        <div className={`w-[45%] pr-2 py-0.5 text-[8.5px] leading-tight flex flex-col justify-center border-r border-black/10 pl-2`}>
          <div className="font-bold mb-0.5 text-gray-600 uppercase text-[9px]">Adres Dostawcy:</div>
          <div>Jungheinrich Polska Sp. Z o.o.</div>
          <div>ul. Świerkowa 3 Bronisze</div>
          <div>05-850 Ożarów Mazowiecki</div>
        </div>
        <div className={`w-[55%] pl-3 py-0.5 flex flex-col justify-center`}>
          <div className="text-[9px] font-bold uppercase tracking-wide text-gray-400">Następny przegląd techniczny</div>
          <div className="text-xl font-bold text-black tracking-tight leading-none">{formattedDate}</div>
        </div>
      </div>
