    const limit = isShelf ? 9 : labelsPerPage;

    if (currentBatch.length > 0 && (isShelf !== currentBatchIsShelf || currentBatch.length >= limit)) {
      pages.push({ plates: currentBatch, grid: currentBatchIsShelf });
      currentBatch = [];
    }

    currentBatchIsShelf = isShelf;
    currentBatch.push(p);
