               <button onClick={performUndo} disabled={undoStack.length === 0} className={`p-2 rounded transition-colors ${undoStack.length === 0 ? 'text-gray-600 cursor-not-allowed' : 'text-orange-400 hover:bg-slate-800 hover:text-white'}`}>
                  <Undo2 size={18} />
