            data.subsequentLevels.map((level, idx) => ( 
              <div key={level.id} className={`flex border-b border-black last:border-b-0`}>
                <div className={`w-[70%] px-3 py-[1px] flex items-center ${borderRight}`}>
                  <span className={`text-[10px] ${labelClass}`}>{idx === 0 ? "Kolejne poziomy" : "\u00A0"}</span>
                </div>
                <div className={`w-[30%] px-2 py-[1px] text-center flex items-baseline justify-center`}>
                  <span className={levelLabelClass}>{`${getLevelLabel(level, 'A')} =`}</span>
                  <span className="text-base font-bold leading-none">{level.height}<span className={unitClass}>mm</span></span>
                </div>
              </div>
            ))
          ) : (
             rows.map((idx) => { 
               const l1 = data.subsequentLevels[idx];
               const l2 = data.subsequentLevels2 ? data.subsequentLevels2[idx] : undefined;
               return (
                <div key={idx} className={`flex border-b border-black last:border-b-0`}>
                  <div className={`w-[70%] px-3 py-[1px] flex items-center ${borderRight}`}>
                    <span className={`text-[10px] ${labelClass}`}>{idx === 0 ? "Kolejne poziomy" : "\u00A0"}</span>
                  </div>
                  <div className={`w-[15%] px-1 py-[1px] text-center flex items-baseline justify-center border-r border-black`}>
                    {l1 && (
                      <div className="flex items-baseline justify-center whitespace-nowrap">
                         <span className="text-[11px] font-bold mr-1 text-gray-700">{`${getLevelLabel(l1, 'A')} =`}</span>
                         <span className="text-sm font-bold leading-none">{l1.height}<span className={unitClass}>mm</span></span>
                      </div>
                    )}
                  </div>
                  <div className={`w-[15%] px-1 py-[1px] text-center flex items-baseline justify-center`}>
                     {l2 && (
                      <div className="flex items-baseline justify-center whitespace-nowrap">
                         <span className="text-[11px] font-bold mr-1 text-gray-700">{`${getLevelLabel(l2, 'B')} =`}</span>
                         <span className="text-sm font-bold leading-none">{l2.height}<span className={unitClass}>mm</span></span>
                      </div>
                    )}
                  </div>
                </div>
               );
             })
          )}
        </div>

        <div className={`bg-white text-black text-center py-0.5 text-[9px] uppercase tracking-tighter shrink-0 font-extrabold border-t-2 border-b-2 border-black leading-none`}>
          Maksymalne obciążenie pary trawersów
        </div>

        {/* Table Header for Beams */}
        <div className={`flex border-b border-black shrink-0 bg-white text-[9px] uppercase font-bold text-gray-600`}>
          <div className={`w-[15%] text-center py-0.5 ${borderRight}`}>Poziom</div>
          <div className={`w-[15%] text-center py-0.5 ${borderRight}`}>Dł. (L)</div>
          <div className={`w-[35%] text-center py-0.5 ${borderRight}`}>Profil</div>
          <div className={`w-[35%] text-center py-0.5`}>Max. Obciążenie</div>
        </div>

        {/* Dynamic Rows: Beams */}
        <div className="flex flex-col shrink-0">
          {data.beams.map((beam) => { 
            const qMax = calculateQmax(beam.loadCount, beam.loadWeight);
            return (
              <div key={beam.id} className={`flex border-b border-black last:border-b-0`}>
                <div className={`w-[15%] flex justify-center items-center px-1 text-sm font-bold ${borderRight} leading-none`}>
                   {beam.levelLabel}
                </div>
                <div className={`w-[15%] flex justify-center items-baseline px-1 text-lg font-bold ${borderRight} leading-none`}>
                  {beam.length}<span className={unitClass}>mm</span>
                </div>
                <div className={`w-[35%] text-center font-bold flex flex-row justify-center items-center gap-1 ${borderRight} leading-none py-0.5`}>
                  <span className="text-base whitespace-nowrap leading-none">{`AUF'B'${beam.profileType}`}</span>
                  <span className="text-[11px] text-gray-400 whitespace-nowrap leading-none">{`(${beam.profileWidth}x50)`}</span>
                </div>
                <div className={`w-[35%] flex flex-col justify-center items-center px-1 py-0.5`}>
                  <div className="flex flex-row items-baseline gap-3 leading-none">
                    <div className="flex items-baseline text-base font-bold leading-none">
                      <span className="text-[9px] mr-1 text-gray-400">Qmax=</span>
                      {qMax}<span className={unitClass}>kg</span>
                    </div>
                    <div className="text-[9px] text-gray-400 leading-none font-semibold">
                      {`${beam.loadCount}x${beam.loadWeight}`}<span className={unitClass}>kg</span>
                    </div>
                  </div>
                </div>
              </div>
            );
          })}
        </div>

        {/* Frame Info */}
        <div className={`flex border-t-2 border-b border-black shrink-0 bg-white`}>
           <div className={`w-[30%] text-center text-[10px] font-bold uppercase py-0.5 ${borderRight} flex items-center justify-center`}>
             <span className={labelClass}>Rama</span>
           </div>
           <div className={`w-[70%] text-center text-base font-bold py-0.5 flex flex-wrap items-center justify-center tracking-tight leading-tight px-1`}>
             {`STD'B'${data.frameType}'${data.frameDepth}'${data.frameHeight}`}
             {data.frameType2 && (
               <span className="text-[10px] mx-1 font-normal text-gray-500 lowercase">oraz</span>
             )}
             {data.frameType2 && (
               <span>{`STD'B'${data.frameType2}'${data.frameDepth2}'${data.frameHeight2}`}</span>
             )}
           </div>
        </div>

        {/* Max Bay Load */}
        <div className={`flex border-b border-black shrink-0 bg-white`}>
           <div className={`w-[60%] px-3 text-[10px] font-bold uppercase py-0.5 ${borderRight} flex items-center leading-none`}>
             <span className={labelClass}>max. obciążenie pola</span>
           </div>
           <div className={`w-[10%] text-center text-xs font-bold py-0.5 ${borderRight} flex items-center justify-center text-gray-600 leading-none`}>
             Qp=
           </div>
           <div className={`w-[30%] text-center text-lg font-bold py-0.5 flex items-baseline justify-center leading-none`}>
             {totalBayLoad}<span className={unitClass}>kg</span>
           </div>
        </div>

        {/* Rack Height */}
        <div className={`flex shrink-0 bg-white`}>
           <div className={`w-[60%] px-3 text-[10px] font-bold uppercase py-0.5 ${borderRight} flex items-center leading-none`}>
             <span className={labelClass}>Wysokość regału</span>
           </div>
           <div className={`w-[10%] text-center text-xs font-bold py-0.5 ${borderRight} flex items-center justify-center text-gray-600 leading-none`}>
             H=
           </div>
           <div className={`w-[30%] text-center text-lg font-bold py-0.5 flex items-baseline justify-center leading-none`}>
             {`${rackHeight}`}<span className={unitClass}>mm</span>
           </div>
        </div>
      </div>

      {/* Footer Address and Inspection - Increased padding top to fix overlap */}
      <div className={`w-[99%] mx-auto flex border-t-2 border-black h-[10mm] shrink-0 mb-1 bg-white relative z-10 mt-auto`}>
        <div className={`w-[45%] pr-2 pt-1.5 pb-0.5 text-[8.5px] leading-tight flex flex-col justify-center border-r border-black/10 pl-2`}>
          <div className="font-bold mb-0.5 text-gray-600 uppercase text-[9px]">Adres Dostawcy:</div>
          <div>Jungheinrich Polska Sp. Z o.o.</div>
          <div>ul. Świerkowa 3 Bronisze</div>
          <div>05-850 Ożarów Mazowiecki</div>
        </div>
        <div className={`w-[55%] pl-3 py-0.5 flex flex-col justify-center`}>
          <div className="text-[9px] font-bold uppercase tracking-wide text-gray-400">Następny przegląd techniczny</div>
          <div className="text-xl font-bold text-black tracking-tight leading-none">{formattedDate}</div>
        </div>
      </div>
    </div>
  );
};

export const PlatePreview: React.FC<Props> = ({ data }) => {
  if (data.type === 'shelf') {
    return <ShelfPlate data={data} />;
  }
  return <PalletPlate data={data} />;
};

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { PlateEditor } from './components/PlateEditor';
import { PlatePreview } from './components/PlatePreview';
import { GlobalEditorModal } from './components/GlobalEditorModal';
import { PlateData, INITIAL_PLATE } from './types';
import { Printer, Plus, FileText, Layout, Layers, Sheet, Download, Upload, FileDown, Settings2, Undo2, Menu, Eye, Edit3, GripVertical, ListOrdered } from 'lucide-react';
import { createDocxBlob } from './utils';

const STORAGE_KEY = 'plateGeneratorData';
const LABELS_PER_PAGE_KEY = 'labelsPerPage';
const MAX_UNDO_STEPS = 50;

const App: React.FC = () => {
  const [plates, setPlates] = useState<PlateData[]>(() => {
    try {
      const saved = localStorage.getItem(STORAGE_KEY);
      return saved ? JSON.parse(saved) : [{ ...INITIAL_PLATE }];
    } catch (e) {
      console.error("Failed to load persistence", e);
      return [{ ...INITIAL_PLATE }];
    }
  });

  const [labelsPerPage, setLabelsPerPage] = useState<number>(() => {
    const saved = localStorage.getItem(LABELS_PER_PAGE_KEY);
    return saved ? parseInt(saved) : 4;
  });

  const [activePlateId, setActivePlateId] = useState<string>(plates[0].id);
  const [viewMode, setViewMode] = useState<'single' | 'sheet'>('single');
  const [mobileTab, setMobileTab] = useState<'editor' | 'preview'>('preview'); 
  const [isGlobalEditorOpen, setIsGlobalEditorOpen] = useState(false);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [leftPanelWidth, setLeftPanelWidth] = useState(60); 
  const [isResizing, setIsResizing] = useState(false);
  const [previewScale, setPreviewScale] = useState(1);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const previewContainerRef = useRef<HTMLDivElement>(null);

  const [undoStack, setUndoStack] = useState<PlateData[][]>([]);
  const lastSavedStateRef = useRef<PlateData[]>(plates);
  const saveTimeoutRef = useRef<number | null>(null);

  const startResizing = useCallback((e: React.MouseEvent) => {
    setIsResizing(true);
    e.preventDefault();
  }, []);

  const stopResizing = useCallback(() => {
    setIsResizing(false);
  }, []);

  const resize = useCallback((e: MouseEvent) => {
    if (isResizing) {
      const newWidth = (e.clientX / window.innerWidth) * 100;
      if (newWidth > 20 && newWidth < 80) {
        setLeftPanelWidth(newWidth);
      }
    }
  }, [isResizing]);

  useEffect(() => {
    window.addEventListener('mousemove', resize);
    window.addEventListener('mouseup', stopResizing);
    return () => {
      window.removeEventListener('mousemove', resize);
      window.removeEventListener('mouseup', stopResizing);
    };
  }, [resize, stopResizing]);

  useEffect(() => {
    const updateScale = () => {
      if (previewContainerRef.current) {
        const containerWidth = previewContainerRef.current.offsetWidth - 40; 
        const plateWidthPx = 190 * 3.78; 
        const newScale = Math.min(containerWidth / plateWidthPx, 1.2);
        setPreviewScale(newScale);
      }
    };

    const observer = new ResizeObserver(updateScale);
    if (previewContainerRef.current) observer.observe(previewContainerRef.current);
    updateScale();

    return () => observer.disconnect();
  }, [leftPanelWidth, viewMode]);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(plates));
  }, [plates]);

  useEffect(() => {
    localStorage.setItem(LABELS_PER_PAGE_KEY, labelsPerPage.toString());
  }, [labelsPerPage]);

  const performUndo = useCallback(() => {
    if (undoStack.length === 0) return;
    const previousState = undoStack[undoStack.length - 1];
    const newStack = undoStack.slice(0, -1);
    setUndoStack(newStack);
    lastSavedStateRef.current = previousState;
    setPlates(previousState);
  }, [undoStack]);

  const updatePlatesWithHistory = (newPlates: PlateData[], immediate = false) => {
    const currentState = lastSavedStateRef.current;
    const saveToStack = () => {
      setUndoStack(prev => {
        const next = [...prev, currentState];
        if (next.length > MAX_UNDO_STEPS) return next.slice(1);
        return next;
      });
      lastSavedStateRef.current = newPlates;
    };

    if (immediate) {
      if (saveTimeoutRef.current) window.clearTimeout(saveTimeoutRef.current);
      saveToStack();
    } else {
      if (saveTimeoutRef.current) window.clearTimeout(saveTimeoutRef.current);
      saveTimeoutRef.current = window.setTimeout(saveToStack, 500);
    }
    setPlates(newPlates);
  };

  useEffect(() => {
    if (!plates.find(p => p.id === activePlateId)) {
      setActivePlateId(plates[0]?.id || '');
    }
  }, [plates, activePlateId]);

  const activePlate = plates.find(p => p.id === activePlateId) || plates[0];

  const updateActivePlate = (newData: PlateData) => {
    const newPlates = plates.map(p => p.id === newData.id ? newData : p);
    updatePlatesWithHistory(newPlates);
  };

  const applyGlobalUpdates = (updates: Partial<PlateData>) => {
    const newPlates = plates.map(p => ({ ...p, ...updates }));
    updatePlatesWithHistory(newPlates, true);
  };

  const addNewPlateConfig = () => {
    const newId = Math.random().toString(36).substr(2, 9);
    const newPlate: PlateData = { ...INITIAL_PLATE, id: newId };
    const newPlates = [...plates, newPlate];
    updatePlatesWithHistory(newPlates, true);
    setActivePlateId(newId);
  };

  const duplicatePlate = (plate: PlateData) => {
    const newId = Math.random().toString(36).substr(2, 9);
    const newPlate = { ...plate, id: newId };
    const newPlates = [...plates, newPlate];
    updatePlatesWithHistory(newPlates, true);
    setActivePlateId(newId);
  };

  const removePlate = (id: string) => {
    if (plates.length === 1) return;
    const newPlates = plates.filter(p => p.id !== id);
    updatePlatesWithHistory(newPlates, true);
  };

  const handlePrint = () => window.print();

  const handleExport = () => {
    const dataStr = JSON.stringify(plates, null, 2);
    const blob = new Blob([dataStr], { type: "application/json" });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `projekty-tabliczki-${new Date().toISOString().split('T')[0]}.json`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleImportClick = () => {
    fileInputRef.current?.click();
  };

  const handleWordExport = async () => {
    const printQueue: PlateData[] = plates.flatMap(p => Array(p.quantity).fill(p));
    try {
      const blob = await createDocxBlob(printQueue);
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = `tabliczki-${new Date().toISOString().split('T')[0]}.docx`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
    } catch (error) {
      console.error("Failed to generate DOCX", error);
      alert("Błąd podczas generowania pliku Word.");
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const json = JSON.parse(event.target?.result as string);
        if (Array.isArray(json) && json.length > 0 && json[0].id) {
          updatePlatesWithHistory(json, true);
          setActivePlateId(json[0].id);
        } else {
          alert("Nieprawidłowy format pliku JSON.");
        }
      } catch (err) {
        alert("Błąd podczas odczytu pliku.");
      }
    };
    reader.readAsText(file);
    e.target.value = '';
  };

  // Sort plates by type (Pallet first, then Shelf) to group them together on pages
  const printQueue: PlateData[] = [...plates]
    .sort((a, b) => {
      if (a.type === b.type) return 0;
      return a.type === 'shelf' ? 1 : -1;
    })
    .flatMap(p => Array(p.quantity).fill(p));

  const pages: { plates: PlateData[], grid: boolean }[] = [];
  let currentBatch: PlateData[] = [];
  let currentBatchIsShelf = false;

  printQueue.forEach(p => {
    const isShelf = p.type === 'shelf';
    const limit = isShelf ? 9 : labelsPerPage;

    if (currentBatch.length > 0 && (isShelf !== currentBatchIsShelf || currentBatch.length >= limit)) {
      pages.push({ plates: currentBatch, grid: currentBatchIsShelf });
      currentBatch = [];
    }

    currentBatchIsShelf = isShelf;
    currentBatch.push(p);
  });

  if (currentBatch.length > 0) {
    pages.push({ plates: currentBatch, grid: currentBatchIsShelf });
  }

  return (
    <div className={`flex flex-col h-screen bg-gray-50 print:h-auto print:overflow-visible ${isResizing ? 'cursor-col-resize select-none' : ''}`}>
      {/* HEADER SECTION */}
      <header className="no-print bg-slate-900 text-white p-2 md:p-3 shadow-lg z-30 shrink-0">
        <div className="w-full px-2 md:px-4 flex justify-between items-center">
          <div className="flex items-center gap-2">
            <button 
              onClick={() => setIsSidebarOpen(!isSidebarOpen)}
              className="p-2 hover:bg-slate-800 rounded-lg lg:2xl:hidden block"
            >
              <Menu size={20} />
            </button>
            <Layout className="w-6 h-6 text-blue-400 hidden sm:block" />
            <h1 className="text-lg md:text-xl font-bold truncate">Generator Tabliczek</h1>
          </div>

          <div className="flex items-center gap-1 md:gap-2">
             <div className="flex items-center gap-1 mr-1 md:mr-2 border-r border-slate-700 pr-2 md:pr-3">
               <button onClick={performUndo} disabled={undoStack.length === 0} className={`p-2 rounded transition-colors ${undoStack.length === 0 ? 'text-gray-600 cursor-not-allowed' : 'text-orange-400 hover:bg-slate-800 hover:text-white'}`}>
                  <Undo2 size={18} />
               </button>
               <button onClick={() => setIsGlobalEditorOpen(true)} className="p-2 rounded text-yellow-400 hover:bg-slate-800 transition-colors" title="Edycja masowa">
                  <Settings2 size={18} />
               </button>
               <button onClick={handleWordExport} className="p-2 rounded text-blue-300 hover:bg-slate-800 transition-colors hidden sm:block">
                  <FileDown size={18} />
               </button>
               <button onClick={handleImportClick} className="p-2 rounded text-emerald-400 hover:bg-slate-800 transition-colors">
                  <Upload size={18} />
               </button>
               <button onClick={handleExport} className="p-2 rounded text-gray-400 hover:bg-slate-800 transition-colors hidden sm:block">
                  <Download size={18} />
               </button>
               <input type="file" accept=".json" ref={fileInputRef} onChange={handleFileChange} className="hidden" />
             </div>
             <button onClick={handlePrint} className="bg-blue-600 hover:bg-blue-500 text-white px-3 md:px-4 py-2 rounded font-semibold flex items-center gap-2 transition-colors text-sm shadow-lg whitespace-nowrap">
              <Printer size={18} />
              <span className="hidden sm:inline">Drukuj</span> <span className="text-[10px] opacity-80">({printQueue.length})</span>
             </button>
          </div>
        </div>
      </header>

      {/* MOBILE TAB SELECTOR */}
      <div className="no-print lg:hidden flex bg-white border-b z-20 shadow-sm shrink-0">
        <button onClick={() => setMobileTab('preview')} className={`flex-1 py-3 flex items-center justify-center gap-2 text-sm font-bold border-b-2 transition-colors ${mobileTab === 'preview' ? 'border-blue-600 text-blue-600 bg-blue-50' : 'border-transparent text-gray-500'}`}>
          <Eye size={16} /> Podgląd
        </button>
        <button onClick={() => setMobileTab('editor')} className={`flex-1 py-3 flex items-center justify-center gap-2 text-sm font-bold border-b-2 transition-colors ${mobileTab === 'editor' ? 'border-blue-600 text-blue-600 bg-blue-50' : 'border-transparent text-gray-500'}`}>
          <Edit3 size={16} /> Edycja
        </button>
      </div>

      {/* MAIN APPLICATION VIEW */}
      <main className="no-print flex-1 flex overflow-hidden w-full relative">
        <aside className={`${isSidebarOpen ? 'translate-x-0' : '-translate-x-full 2xl:translate-x-0'} fixed 2xl:static top-0 left-0 h-full z-40 2xl:z-0 w-72 bg-white border-r overflow-y-auto flex flex-col transition-transform duration-300`}>
          <div className="p-4 border-b bg-gray-50 flex justify-between items-center sticky top-0 z-10">
             <span className="font-bold text-gray-700 text-sm">Twoje Projekty</span>
             <button onClick={addNewPlateConfig} className="bg-green-600 text-white p-1.5 rounded hover:bg-green-700 shadow-sm"><Plus size={16} /></button>
          </div>
          <div className="flex-1 p-2 space-y-2">
            {plates.map((plate, index) => (
              <div 
                key={plate.id}
                onClick={() => { setActivePlateId(plate.id); if (window.innerWidth < 1536) setIsSidebarOpen(false); }}
                className={`p-3 rounded-xl cursor-pointer border transition-all ${activePlateId === plate.id ? 'border-blue-500 bg-blue-50 shadow-md ring-2 ring-blue-100' : 'border-gray-200 hover:border-blue-300'}`}
              >
                <div className="flex justify-between items-start mb-1">
                  <div className="font-bold text-gray-800 text-xs">#{index + 1} {plate.type === 'shelf' ? 'Półkowy' : 'Paletowy'}</div>
                  <div className="bg-white border text-blue-600 text-[10px] px-2 py-0.5 rounded-full font-bold">{plate.quantity} szt.</div>
                </div>
                <div className="text-[11px] text-gray-600 truncate mt-1 font-semibold">{plate.customerName || 'Brak nazwy'}</div>
              </div>
            ))}
          </div>
        </aside>

        <div className="flex-1 flex overflow-hidden">
          <section ref={previewContainerRef} className={`${mobileTab === 'preview' ? 'flex' : 'hidden lg:flex'} bg-gray-200/50 flex flex-col border-r overflow-hidden`} style={{ width: window.innerWidth >= 1024 ? `${leftPanelWidth}%` : '100%' }}>
            <div className="p-3 flex justify-between items-center bg-white border-b shadow-sm shrink-0">
               <h3 className="text-gray-700 font-bold flex items-center gap-2 text-xs uppercase tracking-wider">
                <FileText size={16} className="text-blue-500" /> Podgląd
              </h3>
              <div className="flex items-center gap-2">
                {viewMode === 'sheet' && activePlate?.type !== 'shelf' && (
                  <div className="flex items-center gap-2 border-r pr-4">
                    <span className="text-[10px] font-black text-gray-400 uppercase">Etykiet / stronę:</span>
                    <div className="flex bg-gray-100 rounded-lg p-0.5">
                      {[2, 3, 4].map(num => (
                        <button key={num} onClick={() => setLabelsPerPage(num)} className={`w-7 h-7 flex items-center justify-center rounded-md text-[11px] font-black transition-all ${labelsPerPage === num ? 'bg-white shadow text-blue-600' : 'text-gray-500'}`}>{num}</button>
                      ))}
                    </div>
                  </div>
                )}
                <div className="flex bg-gray-100 rounded-lg p-1">
                   <button onClick={() => setViewMode('single')} className={`px-3 py-1.5 rounded-md text-[11px] font-bold transition-all ${viewMode === 'single' ? 'bg-white shadow text-blue-600' : 'text-gray-500'}`}>Pojedyncza</button>
                   <button onClick={() => setViewMode('sheet')} className={`px-3 py-1.5 rounded-md text-[11px] font-bold transition-all ${viewMode === 'sheet' ? 'bg-white shadow text-blue-600' : 'text-gray-500'}`}>Arkusze</button>
                </div>
              </div>
            </div>

            <div className="flex-1 overflow-auto p-4 flex justify-center items-start bg-slate-200/30">
               {viewMode === 'single' ? (
                  <div className="bg-white shadow-2xl origin-top rounded-sm transition-transform" style={{ transform: `scale(${previewScale})` }}>
                     {activePlate && <PlatePreview data={activePlate} />}
                  </div>
                ) : (
                  <div className="flex flex-col gap-8 origin-top transition-transform" style={{ transform: `scale(${previewScale * (activePlate?.type === 'shelf' ? 0.9 : 0.7)})` }}>
                    {pages.map((page, pageIdx) => (
                      <div key={pageIdx} className="bg-white shadow-2xl relative flex flex-col items-center overflow-hidden" style={{ width: '210mm', height: '297mm' }}>
                         <div className="absolute top-4 left-4 text-gray-200 font-black text-6xl select-none pointer-events-none">A4 - {pageIdx + 1}</div>
                         <div className={`w-full h-full ${page.grid ? 'grid grid-cols-3 grid-rows-3 gap-y-4 gap-x-2 p-4' : 'flex flex-col gap-6 justify-center'}`}>
                            {page.plates.map((plate, idx) => (
                              <div key={`${plate.id}-${idx}`} 
                                className={`flex justify-center items-center w-full`}
                              >
                                <PlatePreview data={plate} />
                              </div>
                            ))}
                         </div>
                      </div>
                    ))}
                  </div>
                )}
            </div>
          </section>

          <div onMouseDown={startResizing} className="hidden lg:flex w-1 bg-gray-300 hover:bg-blue-400 cursor-col-resize items-center justify-center">
            <div className="w-4 h-12 bg-gray-200 border rounded-full flex items-center justify-center shadow-sm"><GripVertical size={14} className="text-gray-400" /></div>
          </div>

          <section className={`${mobileTab === 'editor' ? 'flex' : 'hidden lg:flex'} flex-1 bg-gray-100 p-3 md:p-8 overflow-y-auto`}>
            <div className="max-w-3xl mx-auto w-full">
              {activePlate && <PlateEditor data={activePlate} onChange={updateActivePlate} onDuplicate={() => duplicatePlate(activePlate)} onRemove={() => removePlate(activePlate.id)} />}
            </div>
          </section>
        </div>
      </main>

      {/* PRINT-ONLY SECTION */}
      <div className="hidden print:block bg-white w-full h-auto">
           {pages.map((page, pageIdx) => (
             <div 
               key={pageIdx} 
               className="print-page flex flex-col" 
               style={{ width: '210mm', minHeight: '297mm', margin: '0 auto', padding: '5mm' }}
             >
                <div className={`w-full h-full ${page.grid ? 'grid grid-cols-3 grid-rows-3 items-center justify-items-center gap-2' : 'flex flex-col gap-6 justify-center'}`}>
                  {page.plates.map((plate, plateIdx) => (
                    <div key={`${plate.id}-${pageIdx}-${plateIdx}`} 
                      className="flex justify-center items-center w-full plate-container"
                    >
                      <PlatePreview data={plate} />
                    </div>
                  ))}
                </div>
             </div>
           ))}
      </div>

      <GlobalEditorModal isOpen={isGlobalEditorOpen} onClose={() => setIsGlobalEditorOpen(false)} currentTemplate={activePlate} onApply={applyGlobalUpdates} />
    </div>
  );
};

