import React from 'react';
import { PlateData, BeamConfig, LevelConfig, BEAM_PROFILES, PlateType } from '../types';
// Added missing Layers icon import from lucide-react
import { Plus, Trash2, RotateCcw, X, ClipboardList, Ruler, Box, HardHat, Info, Hash, Settings, Package, Layers } from 'lucide-react';
import { calculateMaxBayLoad, calculateTotalHeight, getLevelRowCount } from '../utils';

interface Props {
  data: PlateData;
  onChange: (data: PlateData) => void;
  onDuplicate: () => void;
  onRemove: () => void;
}

export const PlateEditor: React.FC<Props> = ({ data, onChange, onDuplicate, onRemove }) => {

  const updateField = <K extends keyof PlateData>(field: K, value: PlateData[K]) => {
    onChange({ ...data, [field]: value });
  };

  const addLevel = () => {
    const lastLevel = data.subsequentLevels[data.subsequentLevels.length - 1];
    const nextStart = lastLevel ? (lastLevel.levelEnd || lastLevel.levelStart) + 1 : 1;
    const newLevel: LevelConfig = {
      id: Math.random().toString(36).substr(2, 9),
      levelStart: nextStart,
      height: 1250
    };
    updateField('subsequentLevels', [...data.subsequentLevels, newLevel]);
  };

  const removeLevel = (id: string) => {
    updateField('subsequentLevels', data.subsequentLevels.filter(l => l.id !== id));
  };

  const updateLevel = (id: string, field: keyof LevelConfig, value: string | number) => {
    const updated = data.subsequentLevels.map(l => l.id === id ? { ...l, [field]: value } : l);
    updateField('subsequentLevels', updated);
  };

  const addLevel2 = () => {
    const lastLevel = (data.subsequentLevels2 || [])[(data.subsequentLevels2 || []).length - 1];
    const nextStart = lastLevel ? (lastLevel.levelEnd || lastLevel.levelStart) + 1 : 1;
    const newLevel: LevelConfig = {
      id: Math.random().toString(36).substr(2, 9),
      levelStart: nextStart,
      height: 1250
    };
    updateField('subsequentLevels2', [...(data.subsequentLevels2 || []), newLevel]);
  };

  const removeLevel2 = (id: string) => {
    updateField('subsequentLevels2', (data.subsequentLevels2 || []).filter(l => l.id !== id));
  };

  const updateLevel2 = (id: string, field: keyof LevelConfig, value: string | number) => {
    const updated = (data.subsequentLevels2 || []).map(l => l.id === id ? { ...l, [field]: value } : l);
    updateField('subsequentLevels2', updated);
  };

  const addBeam = () => {
    const newBeam: BeamConfig = {
      id: Math.random().toString(36).substr(2, 9),
      levelLabel: 'A',
      length: 2700,
      profileType: "E0485/15",
      profileWidth: 125,
      loadCount: 3,
      loadWeight: 400
    };
    updateField('beams', [...data.beams, newBeam]);
  };

  const removeBeam = (id: string) => {
    updateField('beams', data.beams.filter(b => b.id !== id));
  };

  const updateBeam = (id: string, field: keyof BeamConfig, value: string | number) => {
    let updatedBeams = data.beams.map(b => b.id === id ? { ...b, [field]: value } : b);

    if (field === 'profileType') {
      const selectedProfile = BEAM_PROFILES.find(p => p.type === value);
      if (selectedProfile) {
        updatedBeams = updatedBeams.map(b => b.id === id ? { ...b, profileWidth: selectedProfile.h } : b);
      }
    }

    updateField('beams', updatedBeams);
  };

  const calculatedBayLoad = calculateMaxBayLoad(data);
  const calculatedTotalHeight = calculateTotalHeight(data);

  return (
    <div className="space-y-5 pb-8 font-mono">
      {/* Header Actions */}
      <div className="bg-white p-3 rounded-xl shadow-sm border border-slate-200 flex justify-between items-center no-print">
        <div className="flex items-center gap-3">
          <div className="w-9 h-9 bg-slate-800 rounded-lg flex items-center justify-center text-white shadow-md">
            <ClipboardList size={20} />
          </div>
          <div>
            <h2 className="text-sm font-bold text-slate-800 leading-tight">PARAMETRY KONFIGURACJI</h2>
            <p className="text-[10px] text-slate-500 font-medium">ID: <span className="text-blue-600">{data.id}</span></p>
          </div>
        </div>
        <div className="flex gap-2">
          <button 
            onClick={onDuplicate} 
            className="flex items-center gap-1.5 text-[10px] font-bold bg-slate-100 text-slate-700 px-3 py-1.5 rounded-lg hover:bg-slate-200 transition-all border border-slate-200"
          >
            DUPLIKUJ
          </button>
          <button 
            onClick={onRemove} 
            className="flex items-center gap-1.5 text-[10px] font-bold bg-red-50 text-red-600 px-3 py-1.5 rounded-lg hover:bg-red-100 transition-all border border-red-100"
          >
            <Trash2 size={12} /> USUŃ
          </button>
        </div>
      </div>

      {/* Type Selector */}
      <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden no-print">
        <div className="bg-slate-800 px-4 py-2 border-b border-slate-700 flex items-center gap-2">
          <Settings size={16} className="text-slate-400" />
          <h3 className="text-[11px] font-bold text-slate-100 uppercase tracking-wider">Rodzaj Regału</h3>
        </div>
        <div className="p-4 flex gap-3">
          <button 
            onClick={() => updateField('type', 'pallet')}
            className={`flex-1 flex items-center justify-center gap-2 py-3 rounded-lg border-2 transition-all font-bold text-xs ${data.type === 'pallet' ? 'border-blue-600 bg-blue-50 text-blue-700 shadow-md' : 'border-slate-100 bg-white text-slate-400 hover:border-slate-200'}`}
          >
            <Layers size={16} /> REGAŁ PALETOWY
          </button>
          <button 
            onClick={() => updateField('type', 'shelf')}
            className={`flex-1 flex items-center justify-center gap-2 py-3 rounded-lg border-2 transition-all font-bold text-xs ${data.type === 'shelf' ? 'border-blue-600 bg-blue-50 text-blue-700 shadow-md' : 'border-slate-100 bg-white text-slate-400 hover:border-slate-200'}`}
          >
            <Package size={16} /> REGAŁ PÓŁKOWY
          </button>
        </div>
      </div>

      {/* Basic Data Section */}
      <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden no-print">
        <div className="bg-slate-800 px-4 py-2 border-b border-slate-700 flex items-center gap-2">
          <Hash size={16} className="text-slate-400" />
